				if pl == p then
					task.defer(function()
						if View.target == p then
							Cmd.set("view", false, nil, true)
							notify("Spectate", p.DisplayName .. " left the game", "info")
						end
					end)
				end
			end))
			return true
		end,
		stop = function()
			View.target = nil
			local cam, h = workspace.CurrentCamera, hum()
			if cam and h then pcall(function() cam.CameraSubject = h end) end
		end,
