	MP.ytKeyBox = Ctl.input(ov, 6, "Converter key (if it needs one)", "leave empty if it doesn't", function() return S.ytKey ~= "" and ("saved  ·  ends in " .. string.sub(S.ytKey, -4)) or "" end, function(x)
		x = Util.trim(x)
