	end)
	MP.ytKeyBox.box.ClearTextOnFocus = true

	section(ov, "Playback", 7)
	MP.optRows = {
		Ctl.toggle(ov, 8, "Fade in and out", "Songs fade instead of cutting off", function() return Player.cfg.fade end, function(x)
			Player.cfg.fade = x
