		end
		Player.lib, Player.queue, Player.ctx, Player.base, Player.ctxPos = {}, {}, {}, {}, 0
		Player.reindex()
		Player.save()
		Bus.fire("playerLib")
		Bus.fire("player")
		notify("Music Player", "Library cleared", "ok", 2)
	end, true)
	section(ov, "YouTube on this executor", 40)
	MP.checkBox = UI.new("Frame", { Name = "TubeCheck", BackgroundColor3 = T.card, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 41, Visible = false }, ov)
	UI.corner(MP.checkBox, 12)
	UI.pad(MP.checkBox, 12, 12, 10, 12)
	UI.list(MP.checkBox, 6)
	MP.checkBtn = Ctl.action(ov, 42, "Check if YouTube songs work here", "badge-check", false, function() MP.tubeCheck() end)
	Ctl.note(ov, 43, "It tries everything YouTube songs need on your executor and tells you what works. Nothing is changed.")
	Ctl.note(ov, 44, "Should work on executors with full file and web support (100% sUNC), like Wave, Volt, Potassium, Velocity, Real, Volcano, Delta, Opiumware and MacSploit. Xeno, Solara and JJSploit are hit or miss, and external ones like Matcha or Severe can't do it.")
end

function MP.tubeCheck()
	if MP.checking then return end
	MP.checking = true
	local box = MP.checkBox
	clearList(box)
	box.Visible = true
	local ex = "this executor"
	pcall(function()
		if X.identifyexecutor then
			local n, v = X.identifyexecutor()
			if type(n) == "string" and n ~= "" then ex = n .. ((type(v) == "string" and v ~= "") and (" " .. v) or "") end
		end
	end)
	local head = UI.label(box, { Text = "Checking " .. ex .. "...", Font = FONT_B, TextSize = 12, Size = UDim2.new(1, 0, 0, 18), LayoutOrder = 1 })
	local n = 1
	local function row(ok, title, detail)
		n += 1
		local r = UI.new("Frame", { Name = "Row", BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = n }, box)
		local col = ok == true and T.green or (ok == false and T.red or T.yellow)
		UI.icon(ok == true and "check" or (ok == false and "x" or "circle-alert"), 13, col, r, { Position = UDim2.fromOffset(0, 2) })
		UI.label(r, { Text = title, TextSize = 11, Font = FONT_B, TextColor3 = T.text, Position = UDim2.fromOffset(20, 0), Size = UDim2.new(1, -20, 0, 16) })
		if detail and detail ~= "" then
			UI.label(r, { Text = detail, TextSize = 10, TextColor3 = T.sub, TextWrapped = true, TextYAlignment = Enum.TextYAlignment.Top, Position = UDim2.fromOffset(20, 16), Size = UDim2.new(1, -20, 0, 0), AutomaticSize = Enum.AutomaticSize.Y })
		end
		return ok
	end
	task.spawn(function()
		local need = true
		if not row(X.request ~= nil, "Web requests", X.request and "It can talk to YouTube" or "No request function, YouTube can't be reached") then need = false end
		local binOk = false
		if X.request then
			local ok, data = Net.get(Repo.raw(HUB_DIR .. "/logo.png"))
			binOk = ok and type(data) == "string" and #data > 1000 and string.sub(data, 1, 8) == "\137PNG\r\n\26\n"
			row(binOk, "Downloads come through whole", binOk and "Song files arrive in one piece" or "Downloaded files come back broken, songs can't play")
			if not binOk then need = false end
		end
		local fsOk = false
		local testPath = LOCAL_DIR .. "/cache/check.bin"
		if HAS_FS then
			local blob = "\0\1\2\255\254" .. string.rep("\0", 32)
			FS.write(testPath, blob)
			fsOk = FS.read(testPath) == blob
		end
		if not row(fsOk, "Saves files", fsOk and "It can keep songs on your device" or "It can't save files the right way") then need = false end
		local assetOk = false
		if fsOk and X.getcustomasset then
			local ok, id = pcall(X.getcustomasset, testPath)
			assetOk = ok and type(id) == "string" and id ~= ""
		end
		if not row(assetOk, "Opens saved files in the game", assetOk and "getcustomasset works" or "No getcustomasset, saved songs can't be opened") then need = false end
		pcall(function() FS.delete(testPath) end)
		local vfOk = pcall(function()
			local f = Instance.new("VideoFrame")
			f:Destroy()
		end)
		if not row(vfOk, "Can play the audio", vfOk and "The game can play the song files" or "VideoFrame is blocked here") then need = false end
		local reach = nil
		if X.request then
			local okS, list = pcall(Tube.search, "never gonna give you up")
			reach = okS and type(list) == "table" and #list > 0
			row(reach, "YouTube answers", reach and "Search works" or "YouTube didn't answer, it might be your internet or YouTube blocking it")
		end
		local cached = nil
		pcall(function()
			for _, p in ipairs(X.listfiles and X.listfiles(Tube.dir) or {}) do
				if string.find(tostring(p), "%.webm$") then
					cached = tostring(p)
					break
				end
			end
		end)
		local playOk = nil
		if cached and assetOk and vfOk then
			local ok, id = pcall(X.getcustomasset, cached)
			if ok and type(id) == "string" then
				local f = Instance.new("VideoFrame")
				f.Visible = false
				f.Volume = 0
				f.Video = id
				f.Parent = Gui
				local t0 = os.clock()
				while os.clock() - t0 < 5 and not f.IsLoaded do
					task.wait(0.1)
				end
				playOk = f.IsLoaded == true
				f:Destroy()
			end
			row(playOk, "Played a saved song", playOk and "A song you played before loaded fine" or "A saved song wouldn't load here")
		else
			row(nil, "Played a saved song", "Play any YouTube song once, then check again to test this too")
		end
		if not HUB.alive then return end
		local works = need and reach ~= false and playOk ~= false
		head.Text = works and ("YouTube songs should work on " .. ex) or ("YouTube songs won't work on " .. ex)
		head.TextColor3 = works and T.green or T.red
		if not works then
			row(nil, "What you can do", "Add a converter link above (they come through as mp3s), or use an executor that has request, getcustomasset and file saving.")
		end
		MP.checking = false
	end)
end

function MP.syncSpotify()
	local c = Spot.connected()
	local free = Spot.free()
	MP.spotOn.Visible = c
	MP.spotFreeOn.Visible = free
	MP.spotFreeSetup.Visible = not c and not free
	MP.spotSetup.Visible = not c
	if free then
		local st = Spot.state
		MP.freeDot.BackgroundColor3 = Spot.err and T.yellow or T.green
		MP.freeInfo.Text = Spot.err or ((st and st.title) and ("Now: " .. st.title) or "Play a song on Spotify and it shows up here")
	end
	if c then
		local bits = {}
		if Spot.state and Spot.state.device then bits[#bits + 1] = "Playing on " .. Spot.state.device end
		if Spot.missingScopes() then bits[#bits + 1] = "log in again for playlists" end
		MP.spotInfo.Text = #bits > 0 and table.concat(bits, "  ·  ") or "Open Spotify on any device to start"
	end
end

MP.onTab = function(i)
	if i == 1 then
		MP.drawUpNext()
		if NP.src == "spotify" then NP.loadQueue(false) end
		NP.each(NP.render, true)
	elseif i == 2 then
		MP.showLyrics()
	elseif i == 3 then
		MP.showLibrary(false)
	elseif i == 5 then
		MP.syncSpotify()
		MP.idBox.render()
		MP.secretBox.render()
		MP.ytBox.render()
		MP.ytKeyBox.render()
		for _, r in ipairs(MP.optRows) do
			r.render(false)
		end
		MP.sleep.render(false)
	end
end

MP.onShow = function()
	MP.srcSwitch(false)
	MP.drawPresets()
	MP.speed.render()
	for _, r in ipairs(MP.fxRows) do
		r.render(false)
	end
	if Spot.live() and not Spot.polling and os.clock() - Spot.lastPoll > 1.5 then task.spawn(Spot.poll) end
	MP.onTab(MP.tab)
end

-- mini player --------------------------------------------------------------------------------------
function NP.openMini()
	local function heightFor(on) return on and 214 or 162 end
	local h = heightFor(S.miniLyrics)
	return Win.show("music_mini", {
		title = "Now playing",
		icon = "music",
		sub = "Music",
		w = 290,
		h = h,
		minW = 240,
		maxW = 420,
		minH = h,
		maxH = h,
		noScroll = true,
		build = function(w, body)
			local on = S.miniLyrics
			if w.h ~= h then
				w.h = h
				w.frame.Size = UDim2.fromOffset(w.w, w.minimized and w.frame.Size.Y.Offset or h)
			end
			local v = { root = body, lyOn = on }
			v.art = NP.art(body, 72, 12, UDim2.fromOffset(0, 2), 24, 5)
			v.title = UI.label(body, { Font = FONT_B, TextSize = 13, Position = UDim2.fromOffset(82, 4), Size = UDim2.new(1, -82, 0, 17), TextTruncate = Enum.TextTruncate.AtEnd })
			v.artist = UI.label(body, { TextSize = 10, TextColor3 = T.sub, Position = UDim2.fromOffset(82, 22), Size = UDim2.new(1, -82, 0, 14), TextTruncate = Enum.TextTruncate.AtEnd })
			local row = UI.new("Frame", { Name = "Controls", BackgroundTransparency = 1, Position = UDim2.fromOffset(82, 40), Size = UDim2.new(1, -82, 0, 34) }, body)
			local prev = NP.button(row, "skip-back", 28, 14, UDim2.new(0, 14, 0.5, 0))
			local play
			play, v.playIcon = NP.button(row, "play-fill", 34, 15, UDim2.new(0, 52, 0.5, 0), true)
			local nxt = NP.button(row, "skip-forward", 28, 14, UDim2.new(0, 90, 0.5, 0))
			prev.Activated:Connect(function() NP.prev() end)
			play.Activated:Connect(function() NP.toggle() end)
			nxt.Activated:Connect(function() NP.next() end)
			local lyb, lyIcon = NP.button(row, "mic-vocal", 28, 13, UDim2.new(1, -16, 0.5, 0))
			lyb.Name = "Lyrics"
			local likeB
			likeB, v.heart = NP.button(row, "heart", 28, 13, UDim2.new(1, -48, 0.5, 0))
			likeB.Activated:Connect(function() NP.like() end)
			local prog = UI.new("Frame", { Name = "Progress", BackgroundTransparency = 1, Position = UDim2.fromOffset(0, 84), Size = UDim2.new(1, 0, 0, 22) }, body)
			NP.bar(prog, v, { Position = UDim2.fromOffset(4, 2), Size = UDim2.new(1, -8, 0, 4) }, true)
			v.tcur = UI.label(prog, { TextSize = 9, TextColor3 = T.sub, Text = "0:00", Position = UDim2.fromOffset(4, 9), Size = UDim2.new(0.5, -4, 0, 12) })
			v.ttotal = UI.label(prog, { TextSize = 9, TextColor3 = T.sub, Text = "-:--", TextXAlignment = Enum.TextXAlignment.Right, AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -4, 0, 9), Size = UDim2.new(0.5, -4, 0, 12) })
			-- the words strip: the lyrics button slides it open and shut, tapping the strip opens all the lyrics
			local box = UI.button(body, { Name = "Words", BackgroundColor3 = T.card, Position = UDim2.fromOffset(0, 110), Size = UDim2.new(1, 0, 0, 50), Visible = on })
			UI.corner(box, 12)
			local bar = UI.new("Frame", { BorderSizePixel = 0, Size = UDim2.new(0, 3, 1, -18), Position = UDim2.fromOffset(9, 9) }, box)
			UI.corner(bar, 2)
			UI.accent(bar, "BackgroundColor3")
			v.lyCur = UI.label(box, { Font = FONT_B, TextSize = 13, Position = UDim2.fromOffset(20, 7), Size = UDim2.new(1, -28, 0, 18), TextTruncate = Enum.TextTruncate.AtEnd, Text = "" })
			v.lyNext = UI.label(box, { TextSize = 10, TextColor3 = T.sub, Position = UDim2.fromOffset(20, 27), Size = UDim2.new(1, -28, 0, 14), TextTruncate = Enum.TextTruncate.AtEnd, Text = "" })
			box.Activated:Connect(function()
				Panel.go("player")
				Panel.setTab(MP, 2)
			end)
			local function paintBtn()
				UI.tint(lyIcon, on and accentColor() or T.text, 0.2)
			end
			paintBtn()
			w:on("accent", function() paintBtn() end)
			local seq = 0
			lyb.Activated:Connect(function()
				on = not on
				S.miniLyrics = on
				saveSettings()
				seq += 1
				local my = seq
				local nh = heightFor(on)
				w.h = nh
				w.def.minH, w.def.maxH, w.def.h = nh, nh, nh
				v.lyOn = on
				v.lyKey = nil
				paintBtn()
				if on then
					box.Visible = true
					pcall(NP.lines, v, NP.info(NP.srcOf(v)))
				end
				Win.fit(w, not S.animations)
				if on or w.minimized or not S.animations then
					box.Visible = on
				else
					task.delay(0.3, function()
						if seq == my and not on and box.Parent then box.Visible = false end
					end)
				end
			end)
			v.extra = function(i)
				w:setTitle(i.has and "Now playing" or "Music", i.src == "spotify" and "Spotify" or "Music Player")
			end
			NP.add(v)
		end,
	})
end

